import{_ as t,o as e,c as o,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"HJ102 字符统计","description":"描述 输入一个只包含小写英文字母和数字的字符串，按照不同字符统计个数由多到少输出统计结果，如果统计的个数相同，则按照ASCII码由小到大排序输出。 数据范围： 输入描述： 一个只包含小写英文字母和数字的字符串。 输出描述： 一个字符串，为不同字母出现次数的降序表示。若出现次数相同。","frontmatter":{"title":"HJ102 字符统计","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 输入一个只包含小写英文字母和数字的字符串，按照不同字符统计个数由多到少输出统计结果，如果统计的个数相同，则按照ASCII码由小到大排序输出。 数据范围： 输入描述： 一个只包含小写英文字母和数字的字符串。 输出描述： 一个字符串，为不同字母出现次数的降序表示。若出现次数相同。","sidebarWeight":52,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/HJ102 字符统计.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ102 字符统计.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ102 字符统计.md"}'),r={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ102 字符统计.md"};function n(s,a,c,l,d,p){return e(),o("div",null,[...a[0]||(a[0]=[i('<div><h1 id="hj102-字符统计" tabindex="-1">HJ102 字符统计 <a class="header-anchor" href="#hj102-字符统计" aria-label="Permalink to &quot;HJ102 字符统计&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ102 字符统计”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 <strong>描述</strong> 输入一个只包含小写英文字母和数字的字符串，按照不同字符统计个数由多到少输出统计结果，如果统计的个数相同，则按照ASCII码由小到大排序输出。 数据范围：</p></blockquote><p><strong>输入描述：</strong> 一个只包含小写英文字母和数字的字符串。 <strong>输出描述：</strong> 一个字符串，为不同字母出现次数的降序表示。若出现次数相同，则按ASCII码的升序输出。 <strong>示例1</strong> 输入： aaddccdc ==复制== 输出： cda ==复制== 说明： 样例里，c和d出现3次，a出现2次，但c的ASCII码比d小，所以先输出c，再输出d，最后输出a.</p><p>要解决这个问题，我们可以先统计字符串中每个字符出现的次数，然后根据字符出现的次数和ASCII码进行排序。</p><p>具体步骤如下：</p><ol><li>使用字典统计每个字符出现的次数。</li><li>将统计结果转换为一个列表，其中每个元素是一个包含字符和其出现次数的元组。</li><li>对这个列表进行排序，先按出现次数降序排序，如果出现次数相同，则按字符的ASCII码升序排序。</li><li>根据排序后的列表构建最终的字符串。</li></ol><h1 id="输入字符串" tabindex="-1">输入字符串 <a class="header-anchor" href="#输入字符串" aria-label="Permalink to &quot;输入字符串&quot;">​</a></h1><p>s = input()</p><h1 id="使用字典统计每个字符出现的次数" tabindex="-1">使用字典统计每个字符出现的次数 <a class="header-anchor" href="#使用字典统计每个字符出现的次数" aria-label="Permalink to &quot;使用字典统计每个字符出现的次数&quot;">​</a></h1><p>char_count = {} for char in s: if char in char_count: char_count[char] += 1 else: char_count[char] = 1</p><h1 id="将统计结果转换为列表-每个元素是-字符-出现次数-的元组" tabindex="-1">将统计结果转换为列表，每个元素是(字符, 出现次数)的元组 <a class="header-anchor" href="#将统计结果转换为列表-每个元素是-字符-出现次数-的元组" aria-label="Permalink to &quot;将统计结果转换为列表，每个元素是(字符, 出现次数)的元组&quot;">​</a></h1><p>count_list = list(char_count.items())</p><h1 id="对列表进行排序-先按出现次数降序-再按ascii码升序" tabindex="-1">对列表进行排序，先按出现次数降序，再按ASCII码升序 <a class="header-anchor" href="#对列表进行排序-先按出现次数降序-再按ascii码升序" aria-label="Permalink to &quot;对列表进行排序，先按出现次数降序，再按ASCII码升序&quot;">​</a></h1><p>count_list.sort(key=lambda x: (-x[1], x[0]))</p><h1 id="构建最终的字符串" tabindex="-1">构建最终的字符串 <a class="header-anchor" href="#构建最终的字符串" aria-label="Permalink to &quot;构建最终的字符串&quot;">​</a></h1><p>result = &#39;&#39;.join([item[0] for item in count_list])</p><h1 id="输出结果" tabindex="-1">输出结果 <a class="header-anchor" href="#输出结果" aria-label="Permalink to &quot;输出结果&quot;">​</a></h1><p>print(result)</p><p>这段代码首先通过遍历输入的字符串<code>input()</code>来统计每个字符出现的次数，并将结果存储在<code>char_count</code>字典中。然后，它将字典转换为包含(字符, 出现次数)元组的列表，并对这个列表进行排序。排序时，首先按出现次数降序（使用<code>-x[1]</code>实现），如果出现次数相同，则按字符的ASCII码升序（直接使用<code>x[0]</code>）。最后，使用列表推导和<code>join</code>方法构建出最终的字符串，并输出。</p><p>input_str = input().strip() count_map = {} for s in input_str: if s in count_map: count_map[s] += 1 else: count_map[s] = 1 new_list = sorted(count_map.items(), key=lambda x: (-x[1], x[0])) print(&#39;&#39;.join([i[0] for i in new_list]))</p></div>',1)])])}const _=t(r,[["render",n]]);export{u as __pageData,_ as default};
